head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > getSubmission]<br/>ID 를 사용하여 특정 Submission 객체를 반환합니다.",
    "validation" : [
        "id(필수) 파라미터로 조회할 Submission 의 ID 를 설정할 수 있어야 합니다.",
        "id 에 해당하는 Submission 객체를 반환해야 합니다.",
        "id 에 해당하는 Submission 이 없으면 null 을 반환해야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getSubmission_onclick = function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1 : XML 에 정의된 Submission 조회
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : XML 정의 Submission 조회 ──");

        var sub = $p.getSubmission("sbm_xml");
        var type = (sub === null) ? "null" : (typeof sub);

        wf_body_bottom.getObj("scwin").setReturnValue(
            "반환 타입: " + type +
            " / id=" + sub.id +
            " / action=" + sub.action +
            " / method=" + sub.method +
            " / mediatype=" + sub.mediatype
        );
    } else if (scenario === "2") {
        // 시나리오 2 : 동적 생성 Submission 조회 + 속성 수정
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : 동적 생성 Submission 조회 + 속성 수정 ──");

        // 이전 실행에서 남아있을 수 있는 submission 정리
        if ($p.getSubmission("sbm_dynamic") !== null) {
            $p.deleteSubmission("sbm_dynamic");
        }

        $p.createSubmission({
            "id" : "sbm_dynamic",
            "action" : "/data/$p_createSubmission_userList.json",
            "method" : "post"
        });

        var sub2 = $p.getSubmission("sbm_dynamic");
        var type2 = (sub2 === null) ? "null" : (typeof sub2);

        wf_body_bottom.getObj("scwin").setReturnValue(
            "반환 타입: " + type2 +
            " / 속성 확인 : action='" + sub2.action + "', method='" + sub2.method + "'"
        );

        // 반환 객체의 속성을 직접 수정
        sub2.action = "/other/path";
        sub2.method = "get";

        // 다시 조회하여 변경 확인
        var sub2Again = $p.getSubmission("sbm_dynamic");
        var sameRef = (sub2 === sub2Again);

        wf_body_bottom.getObj("scwin").setReturnValue(
            "속성 수정 후 재조회 : action='" + sub2Again.action + "', method='" + sub2Again.method +
            "' / 동일 참조 : " + sameRef
        );
    } else if (scenario === "3") {
        // 시나리오 3 : 존재하지 않는 ID 조회 -> null 반환
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : 존재하지 않는 ID 조회 ──");

        var result = $p.getSubmission("not_exist");
        var resultType = (result === null) ? "null (존재하지 않는 ID)" : (typeof result);

        wf_body_bottom.getObj("scwin").setReturnValue("반환값: " + resultType);
    }
};
